1	package clinical
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"reflect"
8		"testing"
9		"time"
10	)
11	
12	// TestCorrectionSaveFailureKeepsRecordAndAudit 覆盖“身份有权操作、患者未停用、
13	// 业务参数合法，但本地保存失败”的更正场景：操作必须明确报错，且正式记录、
14	// 版本历史、审计与接收方读取全部维持提交前的状态；保存条件恢复后，可以用
15	// 失败前的当前版本号成功重试，失败尝试不留下任何痕迹。
16	func TestCorrectionSaveFailureKeepsRecordAndAudit(t *testing.T) {
17		dir := t.TempDir()
18		clk := &fakeClock{t: time.Date(2026, 4, 1, 9, 0, 0, 0, time.UTC)}
19		open := func() *Store {
20			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
21			if err != nil {
22				t.Fatalf("open: %v", err)
23			}
24			return s
25		}
26	
27		s := open()
28		p, err := s.RegisterPatient(doc, "合成患者丙")
29		if err != nil {
30			t.Fatal(err)
31		}
32		e, err := s.AddEncounter(doc, p.ID, time.Time{})
33		if err != nil {
34			t.Fatal(err)
35		}
36		r, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "初诊：高血压 I10")
37		if err != nil {
38			t.Fatal(err)
39		}
40		v1, err := s.ActivateRecord(doc, r.ID)
41		if err != nil {
42			t.Fatal(err)
43		}
44		// 已生效且已有一次成功更正：当前为第 2 版。
45		clk.t = clk.t.Add(time.Hour)
46		v2, err := s.CorrectRecord(doc, r.ID, 1, "复诊：高血压 I10（控制稳定）", "复核更新")
47		if err != nil {
48			t.Fatal(err)
49		}
50		// 接收方持有当前有效的整类授权。
51		if _, err := s.Grant(doc, p.ID, rcv.ID,
52			[]Scope{{EncounterID: e.ID, Category: Diagnosis}},
53			clk.t.Add(-time.Minute), clk.t.Add(24*time.Hour)); err != nil {
54			t.Fatal(err)
55		}
56	
57		// 提交前的基线：当前版本、完整历史、审计与接收方读取结果。
58		chartBefore, err := s.Chart(doc, p.ID)
59		if err != nil {
60			t.Fatal(err)
61		}
62		histBefore := findHistory(chartBefore, r.ID)
63		if histBefore == nil || histBefore.CurrentVersion == nil ||
64			histBefore.CurrentVersion.ID != v2.ID || len(histBefore.Versions) != 2 {
65			t.Fatalf("unexpected baseline history: %+v", histBefore)
66		}
67		auditBefore, err := s.AuditEvents(doc, p.ID)
68		if err != nil {
69			t.Fatal(err)
70		}
71		if got := auditActions(auditBefore); got[ActionActivated] != 1 || got[ActionCorrected] != 1 || got[ActionGranted] != 1 {
72			t.Fatalf("unexpected baseline audit: %v", got)
73		}
74		readBefore, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
75		if err != nil {
76			t.Fatal(err)
77		}
78		if len(readBefore.Records) != 1 || readBefore.Records[0].VersionID != v2.ID {
79			t.Fatalf("unexpected baseline read: %+v", readBefore)
80		}
81	
82		// checkIntact 断言：正式记录、完整历史、审计与接收方读取都与提交前一致，
83		// 失败更正没有留下任何正式版本或更正事件。
84		checkIntact := func(label string, st *Store) {
85			t.Helper()
86	
87			chart, err := st.Chart(doc, p.ID)
88			if err != nil {
89				t.Fatalf("%s: chart: %v", label, err)
90			}
91			hist := findHistory(chart, r.ID)
92			if hist == nil || hist.CurrentVersion == nil {
93				t.Fatalf("%s: history missing: %+v", label, hist)
94			}
95			// 当前版本的标识、版本号、完整内容与生效时间与提交前一致。
96			cur := hist.CurrentVersion
97			if cur.ID != v2.ID || cur.Number != 2 || cur.Content != v2.Content ||
98				!cur.CreatedAt.Equal(v2.CreatedAt) || cur.PrevID != v1.ID || cur.Reason != v2.Reason {
99				t.Fatalf("%s: current version changed: %+v", label, cur)
100			}
101			if hist.Record.CurrentVersionID != v2.ID {
102				t.Fatalf("%s: record current version id changed: %q", label, hist.Record.CurrentVersionID)
103			}
104			// 原有两版的内容、顺序、前一版本关系与原因全部保留，没有多出版本。
105			if len(hist.Versions) != 2 {
106				t.Fatalf("%s: version count changed: %+v", label, hist.Versions)
107			}
108			if !reflect.DeepEqual(hist.Record.Versions, []ID{v1.ID, v2.ID}) {
109				t.Fatalf("%s: version order changed: %v", label, hist.Record.Versions)
110			}
111			if !reflect.DeepEqual(hist.Versions[0], v1) || !reflect.DeepEqual(hist.Versions[1], v2) {
112				t.Fatalf("%s: history versions mutated: %+v", label, hist.Versions)
113			}
114	
115			// 该次就诊的记录视图同样保持原状。
116			er, err := st.EncounterRecords(doc, p.ID, e.ID)
117			if err != nil {
118				t.Fatalf("%s: encounter records: %v", label, err)
119			}
120			if len(er) != 1 || er[0].CurrentVersion == nil || er[0].CurrentVersion.ID != v2.ID ||
121				len(er[0].Versions) != 2 {
122				t.Fatalf("%s: encounter view changed: %+v", label, er)
123			}
124	
125			// 既有审计事件保持原样，失败更正没有新增更正事件。
126			audit, err := st.AuditEvents(doc, p.ID)
127			if err != nil {
128				t.Fatalf("%s: audit: %v", label, err)
129			}
130			if !reflect.DeepEqual(audit, auditBefore) {
131				t.Fatalf("%s: audit events changed:\nbefore: %+v\nafter:  %+v", label, auditBefore, audit)
132			}
133	
134			// 接收方仍读到提交前的当前生效版本，且只有当前版本。
135			res, err := st.Read(rcv, p.ID, e.ID, Diagnosis)
136			if err != nil {
137				t.Fatalf("%s: receiver read: %v", label, err)
138			}
139			if !reflect.DeepEqual(res, readBefore) {
140				t.Fatalf("%s: receiver read changed:\nbefore: %+v\nafter:  %+v", label, readBefore, res)
141			}
142		}
143	
144		// 制造本地保存失败：数据文件原位置被同名目录占据，原子改名必然失败，
145		// 与身份、参数校验无关。原数据文件先挪到旁边，事后原样还原。
146		dataPath := filepath.Join(dir, dataName)
147		backupPath := dataPath + ".saved"
148		if err := os.Rename(dataPath, backupPath); err != nil {
149			t.Fatalf("backup data file: %v", err)
150		}
151		if err := os.Mkdir(dataPath, 0o755); err != nil {
152			t.Fatalf("block data path: %v", err)
153		}
154	
155		// 身份有权、患者未停用、版本号/内容/原因均合法，仅保存失败：明确报错，
156		// 且不能伪装成参数校验或版本冲突等业务结果。
157		if _, err := s.CorrectRecord(doc, r.ID, 2, "未保存的更正内容", "未保存的更正原因"); err == nil {
158			t.Fatal("correction must fail when local save fails")
159		} else if errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrConflict) ||
160			errors.Is(err, ErrAccessDenied) || errors.Is(err, ErrDeactivated) {
161			t.Fatalf("save failure surfaced as a business error: %v", err)
162		}
163		// 失败不能留下半截写入的临时文件。
164		if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
165			t.Fatalf("failed save left a temp file: %v", statErr)
166		}
167	
168		// 失败后：档案、就诊记录、审计与接收方读取全部维持提交前状态。
169		checkIntact("after failed save", s)
170	
171		// 关闭后从原数据位置重新打开：先恢复保存条件（还原原数据文件）。
172		if err := s.Close(); err != nil {
173			t.Fatal(err)
174		}
175		if err := os.Remove(dataPath); err != nil {
176			t.Fatalf("unblock data path: %v", err)
177		}
178		if err := os.Rename(backupPath, dataPath); err != nil {
179			t.Fatalf("restore data file: %v", err)
180		}
181	
182		s2 := open()
183		t.Cleanup(func() { _ = s2.Close() })
184		// 失败前的当前版本、完整历史与审计在重开后完整存在，
185		// 失败更正没有变成正式数据。
186		checkIntact("after reopen", s2)
187	
188		// 保存条件恢复后：用失败前的当前版本号再次提交合法更正，成功生成
189		// 紧接原当前版本的新版本——失败尝试既没有推进版本号，也没有让
190		// 原本有效的当前版本号变成冲突。
191		clk.t = clk.t.Add(time.Hour)
192		v3, err := s2.CorrectRecord(doc, r.ID, 2, "重试成功的更正内容", "保存恢复后重试")
193		if err != nil {
194			t.Fatalf("retry after save recovered: %v", err)
195		}
196		if v3.Number != 3 || v3.PrevID != v2.ID || v3.Reason != "保存恢复后重试" ||
197			v3.Content != "重试成功的更正内容" || !v3.CreatedAt.Equal(clk.t) {
198			t.Fatalf("bad v3: %+v", v3)
199		}
200	
201		chart, err := s2.Chart(doc, p.ID)
202		if err != nil {
203			t.Fatal(err)
204		}
205		hist := findHistory(chart, r.ID)
206		if hist == nil || hist.CurrentVersion == nil || hist.CurrentVersion.ID != v3.ID || len(hist.Versions) != 3 {
207			t.Fatalf("history after retry: %+v", hist)
208		}
209		// 此前历史未被丢失或覆盖。
210		if !reflect.DeepEqual(hist.Versions[0], v1) || !reflect.DeepEqual(hist.Versions[1], v2) {
211			t.Fatalf("prior history mutated by retry: %+v", hist.Versions)
212		}
213	
214		// 只新增一次对应的更正审计：既有事件原样保留，事件总数 +1。
215		audit, err := s2.AuditEvents(doc, p.ID)
216		if err != nil {
217			t.Fatal(err)
218		}
