package clinical

import (
	"errors"
	"os"
	"path/filepath"
	"reflect"
	"testing"
	"time"
)

// TestCorrectionSaveFailureKeepsRecordAndAudit 覆盖“身份有权操作、患者未停用、
// 业务参数合法，但本地保存失败”的更正场景：操作必须明确报错，且正式记录、
// 版本历史、审计与接收方读取全部维持提交前的状态；保存条件恢复后，可以用
// 失败前的当前版本号成功重试，失败尝试不留下任何痕迹。
func TestCorrectionSaveFailureKeepsRecordAndAudit(t *testing.T) {
	dir := t.TempDir()
	clk := &fakeClock{t: time.Date(2026, 4, 1, 9, 0, 0, 0, time.UTC)}
	open := func() *Store {
		s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
		if err != nil {
			t.Fatalf("open: %v", err)
		}
		return s
	}

	s := open()
	p, err := s.RegisterPatient(doc, "合成患者丙")
	if err != nil {
		t.Fatal(err)
	}
	e, err := s.AddEncounter(doc, p.ID, time.Time{})
	if err != nil {
		t.Fatal(err)
	}
	r, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "初诊：高血压 I10")
	if err != nil {
		t.Fatal(err)
	}
	v1, err := s.ActivateRecord(doc, r.ID)
	if err != nil {
		t.Fatal(err)
	}
	// 已生效且已有一次成功更正：当前为第 2 版。
	clk.t = clk.t.Add(time.Hour)
	v2, err := s.CorrectRecord(doc, r.ID, 1, "复诊：高血压 I10（控制稳定）", "复核更新")
	if err != nil {
		t.Fatal(err)
	}
	// 接收方持有当前有效的整类授权。
	if _, err := s.Grant(doc, p.ID, rcv.ID,
		[]Scope{{EncounterID: e.ID, Category: Diagnosis}},
		clk.t.Add(-time.Minute), clk.t.Add(24*time.Hour)); err != nil {
		t.Fatal(err)
	}

	// 提交前的基线：当前版本、完整历史、审计与接收方读取结果。
	chartBefore, err := s.Chart(doc, p.ID)
	if err != nil {
		t.Fatal(err)
	}
	histBefore := findHistory(chartBefore, r.ID)
	if histBefore == nil || histBefore.CurrentVersion == nil ||
		histBefore.CurrentVersion.ID != v2.ID || len(histBefore.Versions) != 2 {
		t.Fatalf("unexpected baseline history: %+v", histBefore)
	}
	auditBefore, err := s.AuditEvents(doc, p.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got := auditActions(auditBefore); got[ActionActivated] != 1 || got[ActionCorrected] != 1 || got[ActionGranted] != 1 {
		t.Fatalf("unexpected baseline audit: %v", got)
	}
	readBefore, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
	if err != nil {
		t.Fatal(err)
	}
	if len(readBefore.Records) != 1 || readBefore.Records[0].VersionID != v2.ID {
		t.Fatalf("unexpected baseline read: %+v", readBefore)
	}

	// checkIntact 断言：正式记录、完整历史、审计与接收方读取都与提交前一致，
	// 失败更正没有留下任何正式版本或更正事件。
	checkIntact := func(label string, st *Store) {
		t.Helper()

		chart, err := st.Chart(doc, p.ID)
		if err != nil {
			t.Fatalf("%s: chart: %v", label, err)
		}
		hist := findHistory(chart, r.ID)
		if hist == nil || hist.CurrentVersion == nil {
			t.Fatalf("%s: history missing: %+v", label, hist)
		}
		// 当前版本的标识、版本号、完整内容与生效时间与提交前一致。
		cur := hist.CurrentVersion
		if cur.ID != v2.ID || cur.Number != 2 || cur.Content != v2.Content ||
			!cur.CreatedAt.Equal(v2.CreatedAt) || cur.PrevID != v1.ID || cur.Reason != v2.Reason {
			t.Fatalf("%s: current version changed: %+v", label, cur)
		}
		if hist.Record.CurrentVersionID != v2.ID {
			t.Fatalf("%s: record current version id changed: %q", label, hist.Record.CurrentVersionID)
		}
		// 原有两版的内容、顺序、前一版本关系与原因全部保留，没有多出版本。
		if len(hist.Versions) != 2 {
			t.Fatalf("%s: version count changed: %+v", label, hist.Versions)
		}
		if !reflect.DeepEqual(hist.Record.Versions, []ID{v1.ID, v2.ID}) {
			t.Fatalf("%s: version order changed: %v", label, hist.Record.Versions)
		}
		if !reflect.DeepEqual(hist.Versions[0], v1) || !reflect.DeepEqual(hist.Versions[1], v2) {
			t.Fatalf("%s: history versions mutated: %+v", label, hist.Versions)
		}

		// 该次就诊的记录视图同样保持原状。
		er, err := st.EncounterRecords(doc, p.ID, e.ID)
		if err != nil {
			t.Fatalf("%s: encounter records: %v", label, err)
		}
		if len(er) != 1 || er[0].CurrentVersion == nil || er[0].CurrentVersion.ID != v2.ID ||
			len(er[0].Versions) != 2 {
			t.Fatalf("%s: encounter view changed: %+v", label, er)
		}

		// 既有审计事件保持原样，失败更正没有新增更正事件。
		audit, err := st.AuditEvents(doc, p.ID)
		if err != nil {
			t.Fatalf("%s: audit: %v", label, err)
		}
		if !reflect.DeepEqual(audit, auditBefore) {
			t.Fatalf("%s: audit events changed:\nbefore: %+v\nafter:  %+v", label, auditBefore, audit)
		}

		// 接收方仍读到提交前的当前生效版本，且只有当前版本。
		res, err := st.Read(rcv, p.ID, e.ID, Diagnosis)
		if err != nil {
			t.Fatalf("%s: receiver read: %v", label, err)
		}
		if !reflect.DeepEqual(res, readBefore) {
			t.Fatalf("%s: receiver read changed:\nbefore: %+v\nafter:  %+v", label, readBefore, res)
		}
	}

	// 制造本地保存失败：数据文件原位置被同名目录占据，原子改名必然失败，
	// 与身份、参数校验无关。原数据文件先挪到旁边，事后原样还原。
	dataPath := filepath.Join(dir, dataName)
	backupPath := dataPath + ".saved"
	if err := os.Rename(dataPath, backupPath); err != nil {
		t.Fatalf("backup data file: %v", err)
	}
	if err := os.Mkdir(dataPath, 0o755); err != nil {
		t.Fatalf("block data path: %v", err)
	}

	// 身份有权、患者未停用、版本号/内容/原因均合法，仅保存失败：明确报错，
	// 且不能伪装成参数校验或版本冲突等业务结果。
	if _, err := s.CorrectRecord(doc, r.ID, 2, "未保存的更正内容", "未保存的更正原因"); err == nil {
		t.Fatal("correction must fail when local save fails")
	} else if errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrConflict) ||
		errors.Is(err, ErrAccessDenied) || errors.Is(err, ErrDeactivated) {
		t.Fatalf("save failure surfaced as a business error: %v", err)
	}
	// 失败不能留下半截写入的临时文件。
	if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
		t.Fatalf("failed save left a temp file: %v", statErr)
	}

	// 失败后：档案、就诊记录、审计与接收方读取全部维持提交前状态。
	checkIntact("after failed save", s)

	// 关闭后从原数据位置重新打开：先恢复保存条件（还原原数据文件）。
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(dataPath); err != nil {
		t.Fatalf("unblock data path: %v", err)
	}
	if err := os.Rename(backupPath, dataPath); err != nil {
		t.Fatalf("restore data file: %v", err)
	}

	s2 := open()
	t.Cleanup(func() { _ = s2.Close() })
	// 失败前的当前版本、完整历史与审计在重开后完整存在，
	// 失败更正没有变成正式数据。
	checkIntact("after reopen", s2)

	// 保存条件恢复后：用失败前的当前版本号再次提交合法更正，成功生成
	// 紧接原当前版本的新版本——失败尝试既没有推进版本号，也没有让
	// 原本有效的当前版本号变成冲突。
	clk.t = clk.t.Add(time.Hour)
	v3, err := s2.CorrectRecord(doc, r.ID, 2, "重试成功的更正内容", "保存恢复后重试")
	if err != nil {
		t.Fatalf("retry after save recovered: %v", err)
	}
	if v3.Number != 3 || v3.PrevID != v2.ID || v3.Reason != "保存恢复后重试" ||
		v3.Content != "重试成功的更正内容" || !v3.CreatedAt.Equal(clk.t) {
		t.Fatalf("bad v3: %+v", v3)
	}

	chart, err := s2.Chart(doc, p.ID)
	if err != nil {
		t.Fatal(err)
	}
	hist := findHistory(chart, r.ID)
	if hist == nil || hist.CurrentVersion == nil || hist.CurrentVersion.ID != v3.ID || len(hist.Versions) != 3 {
		t.Fatalf("history after retry: %+v", hist)
	}
	// 此前历史未被丢失或覆盖。
	if !reflect.DeepEqual(hist.Versions[0], v1) || !reflect.DeepEqual(hist.Versions[1], v2) {
		t.Fatalf("prior history mutated by retry: %+v", hist.Versions)
	}

	// 只新增一次对应的更正审计：既有事件原样保留，事件总数 +1。
	audit, err := s2.AuditEvents(doc, p.ID)
	if err != nil {
		t.Fatal(err)
	}
	if len(audit) != len(auditBefore)+1 || !reflect.DeepEqual(audit[:len(auditBefore)], auditBefore) {
		t.Fatalf("audit after retry:\nbefore: %+v\nafter:  %+v", auditBefore, audit)
	}
	last := audit[len(audit)-1]
	if last.Action != ActionCorrected || last.ObjectID != r.ID || last.ActorID != doc.ID {
		t.Fatalf("unexpected new audit event: %+v", last)
	}
	if got := auditActions(audit)[ActionCorrected]; got != 2 {
		t.Fatalf("corrected events = %d, want 2", got)
	}

	// 成功更正后接收方读到新的当前版本（既有授权行为保持不变）。
	res, err := s2.Read(rcv, p.ID, e.ID, Diagnosis)
	if err != nil {
		t.Fatal(err)
	}
	if len(res.Records) != 1 || res.Records[0].VersionID != v3.ID ||
		res.Records[0].Version != 3 || res.Records[0].Content != v3.Content {
		t.Fatalf("receiver read after retry: %+v", res)
	}
}

package clinical

import (
	"errors"
	"time"
)

// 记录类别：诊断与医嘱。
const (
	Diagnosis = "diagnosis"
	Order     = "order"
)

// 审计动作。
const (
	ActionActivated   = "activated"
	ActionCorrected   = "corrected"
	ActionGranted     = "authorization_granted"
	ActionRevoked     = "authorization_revoked"
	ActionDeactivated = "patient_deactivated"
	ActionExchanged   = "exchange_created"
	ActionReceipted   = "receipt_registered"
)

// 合成数据标记。本包只处理合成患者资料，登记时统一写入。
const SyntheticSource = "synthetic"

// 调用方身份。Internal 为内部使用者，Receiver 为接收方。
//
// 内部使用者可查看全部草稿与完整历史、建立与撤回授权、维护档案；
// 接收方只能凭有效授权读取当前生效版本。
type Actor struct {
	ID   string
	Kind string // "internal" 或 "receiver"
}

// InternalActor 构造一个内部使用者身份。
func InternalActor(id string) Actor { return Actor{ID: id, Kind: "internal"} }

// ReceiverActor 构造一个接收方身份。
func ReceiverActor(id string) Actor { return Actor{ID: id, Kind: "receiver"} }

// IsInternal 报告该身份是否为内部使用者。
func (a Actor) IsInternal() bool { return a.Kind == "internal" }

func (a Actor) valid() bool {
	if a.ID == "" {
		return false
	}
	return a.Kind == "internal" || a.Kind == "receiver"
}

// ID 是患者、就诊、记录、版本、授权与审计事件的稳定标识。
// ID 在各自类型的集合内唯一，由登记操作生成并原样返回，
// 关闭后从同一位置重新打开仍然有效。
type ID = string

// Patient 是一名合成患者的档案。
type Patient struct {
	ID          ID
	Name        string
	Source      string // 始终为 SyntheticSource
	Deactivated bool
	CreatedAt   time.Time
}

// Encounter 是患者的一次就诊。
type Encounter struct {
	ID         ID
	PatientID  ID
	OccurredAt time.Time
	CreatedAt  time.Time
}

// Version 是一条记录在某一时刻被固化的完整内容。
// 生效产生第 1 版；每次更正产生新版本并通过 PrevID 链接到上一版本。
type Version struct {
	ID        ID
	RecordID  ID
	Number    int
	Content   string
	Category  string
	CreatedAt time.Time // 生效或更正发生的时间
	PrevID    ID        // 上一版本；第 1 版为空
	Reason    string    // 更正原因；第 1 版为空
}

// Record 是一条诊断或医嘱。它在草稿与版本之间推进：
// 草稿可反复修改或删除；生效后产生不可变的当前版本，
// 此后只能通过更正产生新版本，不能被直接覆盖或删除。
type Record struct {
	ID          ID
	PatientID   ID
	EncounterID ID
	Category    string

	DraftContent string
	HasDraft     bool

	CurrentVersionID ID
	Versions         []ID // 按版本号顺序，旧到新
}

// Authorization 是内部使用者为一名接收方建立的、针对某患者的读取授权。
// 范围由两类条目组成，二者可并存、均可覆盖多条就诊与类别：
//
//   - Scopes：整类范围，覆盖某次就诊下某个类别（诊断/医嘱）的全部已生效
//     记录，含授权建立之后才生效的记录；读取时始终取记录的当前生效版本。
//   - Selections：限定范围，仅覆盖明确选出的具体记录。被选记录被更正后
//     授权覆盖它的当前版本；但同一就诊同一类别的其他记录、以及后来新增
//     并生效的记录都不会自动进入限定范围。
//
// 授权仅在 [StartsAt, ExpiresAt) 内有效。
type Authorization struct {
	ID         ID
	PatientID  ID
	ReceiverID string
	Scopes     []Scope
	// Selections 为限定范围中明确选出的记录。为空表示该授权只有整类范围；
	// 旧数据与 Grant 建立的授权该字段始终为空。
	Selections []RecordSelection
	StartsAt   time.Time
	ExpiresAt  time.Time
	RevokedAt  *time.Time // 撤回时间；nil 表示未撤回
	CreatedAt  time.Time
}

// ActiveAt 报告授权在时刻 t 是否有效：已开始、未到期、未撤回。
// 开始时刻即生效；到截止时刻立即失效（半开区间 [StartsAt, ExpiresAt)）。
func (a *Authorization) ActiveAt(t time.Time) bool {
	if a.RevokedAt != nil {
		return false
	}
	if t.Before(a.StartsAt) {
		return false
	}
	if !t.Before(a.ExpiresAt) {
		return false
	}
	return true
}

// Scope 是授权范围中的一项：某次就诊下的某个记录类别。
type Scope struct {
	EncounterID ID
	Category    string
}

// RecordSelection 是授权限定范围中的一项：明确选出某条已生效记录，
// 并声明它所属的就诊与类别。建立授权时记录必须存在、已生效、属于该
// 患者，且其实际就诊与类别必须与声明一致；同一记录在一条授权内重复
// 选择只算一次。
type RecordSelection struct {
	EncounterID ID
	Category    string
	RecordID    ID
}

// AuditEvent 是一条仅供内部使用者按患者查看的审计事件。
type AuditEvent struct {
	ID         ID
	PatientID  ID
	ActorID    string
	Action     string
	ObjectType string
	ObjectID   ID
	OccurredAt time.Time
}

// ReadResult 是接收方一次受限读取得到的内容。
type ReadResult struct {
	EncounterID ID
	Category    string
	// Records 为该就诊该类别下、当前生效且被有效授权覆盖的记录，
	// 每项只含当前生效版本的完整内容，不含草稿、旧版本或更正原因。
	Records []EffectiveRecord
}

// EffectiveRecord 是对外暴露的一条当前生效记录。
type EffectiveRecord struct {
	RecordID    ID
	VersionID   ID
	Version     int
	Content     string
	EffectiveAt time.Time
}

// 交换状态：创建后待回执，接收方登记回执后转为已接受或已拒绝。
const (
	ExchangePending  = "pending_receipt"
	ExchangeAccepted = "accepted"
	ExchangeRejected = "rejected"
)

// 回执结果：接受或拒绝打包内容。
const (
	ReceiptAccepted = "accepted"
	ReceiptRejected = "rejected"
)

// PackagedRecord 是包内固化的一条记录版本。包在创建时取各记录的当前生效
// 版本快照：此后记录被更正或新增版本都不会改写包内容。
//
// 只含核对所需的标识、版本号、生效时间与完整内容，不含患者姓名、草稿、
// 历史版本或更正原因（Version.Reason）。
type PackagedRecord struct {
	EncounterID ID
	Category    string
	RecordID    ID
	VersionID   ID
	Version     int
	EffectiveAt time.Time
	Content     string
}

// Package 是一份已固化的交换内容：只含患者与接收方标识及各记录的版本快照。
type Package struct {
	PatientID  ID
	ReceiverID string
	Records    []PackagedRecord
}

// Receipt 是接收方对一份包的回执。接受时 Reason 为空；拒绝时 Reason 必填。
type Receipt struct {
	Outcome      string
	Reason       string
	RegisteredAt time.Time
}

// Exchange 是把已授权记录打包给指定接收方的一次交换。
//
// 创建即把当时的当前版本固化进 Package 并计算摘要；状态初始为待回执。
// 请求号（RequestID）按发起的内部使用者区分，用于安全重试：同一使用者以
// 相同请求号、患者、接收方、绑定授权与记录集合重试时返回原交换。
type Exchange struct {
	ID              ID
	PatientID       ID
	ReceiverID      string
	AuthorizationID ID
	RequestID       string
	CreatorID       string // 创建交换的内部使用者标识
	Status          string // ExchangePending/Accepted/Rejected
	Digest          string // 包内容摘要，接收方回执时须原样回传
	Package         Package
	Receipt         *Receipt
	CreatedAt       time.Time
}

// 失败一律返回明确错误，不留下半条记录。
var (
	// ErrNotFound 表示引用的患者、就诊、记录、版本或授权不存在。
	ErrNotFound = errors.New("clinical: referenced object not found")
	// ErrMismatchedPatient 表示混用了属于不同患者的对象。
	ErrMismatchedPatient = errors.New("clinical: objects belong to different patients")
	// ErrInvalidArgument 表示参数本身不合法（空内容、空范围、时间窗倒置等）。
	ErrInvalidArgument = errors.New("clinical: invalid argument")
	// ErrConflict 表示乐观并发冲突：指定的版本已不再是当前版本。
	ErrConflict = errors.New("clinical: version conflict")
	// ErrDeactivated 表示患者档案已停用，该写操作不再允许。
	ErrDeactivated = errors.New("clinical: patient record is deactivated")
	// ErrActive 表示记录已有生效版本，不能按草稿方式直接覆盖或删除。
	ErrActive = errors.New("clinical: record is already effective")
	// ErrAccessDenied 表示接收方没有覆盖所请求范围的有效授权，
	// 或内部规则不允许该身份执行此操作。返回时不携带任何受保护内容。
	ErrAccessDenied = errors.New("clinical: access denied")
	// ErrClosed 表示 Store 已关闭。
	ErrClosed = errors.New("clinical: store closed")
)

