1	package clinical
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// ---- 测试基础设施 ----
10	
11	type fakeClock struct{ t time.Time }
12	
13	func newTestStore(t *testing.T) (*Store, *fakeClock) {
14		t.Helper()
15		clk := &fakeClock{t: time.Date(2026, 1, 1, 9, 0, 0, 0, time.UTC)}
16		dir := t.TempDir()
17		s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
18		if err != nil {
19			t.Fatalf("open: %v", err)
20		}
21		t.Cleanup(func() { _ = s.Close() })
22		return s, clk
23	}
24	
25	var (
26		doc  = InternalActor("doc-1")
27		doc2 = InternalActor("doc-2")
28		rcv  = ReceiverActor("rcv-a")
29		rcvB = ReceiverActor("rcv-b")
30	)
31	
32	func setupPatientEncounter(t *testing.T, s *Store) (ID, ID) {
33		t.Helper()
34		p, err := s.RegisterPatient(doc, "合成患者甲")
35		if err != nil {
36			t.Fatalf("register patient: %v", err)
37		}
38		e, err := s.AddEncounter(doc, p.ID, time.Time{})
39		if err != nil {
40			t.Fatalf("add encounter: %v", err)
41		}
42		return p.ID, e.ID
43	}
44	
45	func countRecords(s *Store) int {
46		c := 0
47		_ = s.view(func(snap *snapshot) error { c = len(snap.Records); return nil })
48		return c
49	}
50	
51	func auditActions(events []AuditEvent) map[string]int {
52		m := map[string]int{}
53		for _, e := range events {
54			m[e.Action]++
55		}
56		return m
57	}
58	
59	// ---- 基线行为保留 ----
60	
61	func TestReadyStillTrue(t *testing.T) {
62		if !Ready() {
63			t.Fatal("Ready must remain true")
64		}
65	}
66	
67	// ---- 患者与就诊 ----
68	
69	func TestRegisterPatientIsSyntheticAndStableID(t *testing.T) {
70		s, _ := newTestStore(t)
71		p, err := s.RegisterPatient(doc, "合成患者甲")
72		if err != nil {
73			t.Fatalf("register: %v", err)
74		}
75		if p.ID == "" {
76			t.Fatal("patient id empty")
77		}
78		if p.Source != SyntheticSource {
79			t.Fatalf("source = %q, want %q", p.Source, SyntheticSource)
80		}
81		got, err := s.GetPatient(doc, p.ID)
82		if err != nil {
83			t.Fatalf("get: %v", err)
84		}
85		if got.ID != p.ID {
86			t.Fatalf("id not stable: %q vs %q", got.ID, p.ID)
87		}
88	}
89	
90	func TestRegisterPatientRequiresInternal(t *testing.T) {
91		s, _ := newTestStore(t)
92		if _, err := s.RegisterPatient(rcv, "x"); !errors.Is(err, ErrAccessDenied) {
93			t.Fatalf("receiver register err = %v, want ErrAccessDenied", err)
94		}
95		if _, err := s.RegisterPatient(InternalActor(""), "x"); !errors.Is(err, ErrAccessDenied) {
96			t.Fatalf("empty actor err = %v", err)
97		}
98		if _, err := s.RegisterPatient(doc, ""); !errors.Is(err, ErrInvalidArgument) {
99			t.Fatalf("empty name err = %v", err)
100		}
101	}
102	
103	func TestAddEncounterValidation(t *testing.T) {
104		s, _ := newTestStore(t)
105		pid, _ := setupPatientEncounter(t, s)
106	
107		if _, err := s.AddEncounter(doc, "pat_missing", time.Time{}); !errors.Is(err, ErrNotFound) {
108			t.Fatalf("missing patient err = %v, want ErrNotFound", err)
109		}
110	
111		other, err := s.RegisterPatient(doc, "合成患者乙")
112		if err != nil {
113			t.Fatal(err)
114		}
115		// 手工构造“其他患者的就诊 id”直接作为引用：通过第二患者的真实就诊验证。
116		encOther, err := s.AddEncounter(doc, other.ID, time.Time{})
117		if err != nil {
118			t.Fatal(err)
119		}
120		// 在草稿上跨患者引用就诊。
121		if _, err := s.CreateDraft(doc, pid, encOther.ID, Diagnosis, "x"); !errors.Is(err, ErrMismatchedPatient) {
122			t.Fatalf("cross-patient encounter err = %v, want ErrMismatchedPatient", err)
123		}
124	}
125	
126	// ---- 草稿生命周期 ----
127	
128	func TestDraftCRUDAndFailureLeavesNothing(t *testing.T) {
129		s, _ := newTestStore(t)
130		pid, eid := setupPatientEncounter(t, s)
131	
132		before := countRecords(s)
133		if _, err := s.CreateDraft(doc, pid, "enc_missing", Diagnosis, "高血压"); !errors.Is(err, ErrNotFound) {
134			t.Fatalf("missing encounter err = %v", err)
135		}
136		if countRecords(s) != before {
137			t.Fatal("failed create left a record")
138		}
139		if _, err := s.CreateDraft(doc, pid, eid, "bogus", "x"); !errors.Is(err, ErrInvalidArgument) {
140			t.Fatalf("bad category err = %v", err)
141		}
142		if _, err := s.CreateDraft(doc, pid, eid, Diagnosis, "   "); !errors.Is(err, ErrInvalidArgument) {
