161	func TestActivationSnapshotsContentAndTime(t *testing.T) {
162		s, clk := newTestStore(t)
163		pid, eid := setupPatientEncounter(t, s)
164	
165		r, err := s.CreateDraft(doc, pid, eid, Order, "阿司匹林 100mg")
