11	
12	// TestGrantSelectiveSaveFailureKeepsStateAndAllowsRetry 覆盖“内部使用者身份合法、
13	// 患者未停用、就诊/类别/所选记录全部合法、时间窗覆盖操作时间，但本地保存失败”
14	// 的授权创建场景：整类范围与限定范围并存于同一条新授权。
15	//
16	// 保存失败必须以普通错误返回（不能表现为创建成功，也不能伪装成范围或身份不
17	// 合法等业务错误），且授权列表、审计与接收方可见结果全部维持提交前状态——
18	// 不允许出现只有授权没有审计、或只有审计没有授权的半成品，接收方也不能提前
19	// 获得新增范围。保存条件恢复后，提交相同的合法授权必须成功：新增一条完整授权
20	// 及其创建审计，接收方随后读到整类范围覆盖的全部诊断与明确选中的医嘱。
21	func TestGrantSelectiveSaveFailureKeepsStateAndAllowsRetry(t *testing.T) {
22		dir := t.TempDir()
23		clk := &fakeClock{t: time.Date(2026, 6, 1, 9, 0, 0, 0, time.UTC)}
24		open := func() *Store {
25			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
26			if err != nil {
27				t.Fatalf("open: %v", err)
28			}
29			return s
30		}
31	
32		s := open()
33		p, err := s.RegisterPatient(doc, "授权保存失败患者")
34		if err != nil {
35			t.Fatal(err)
36		}
37		e, err := s.AddEncounter(doc, p.ID, time.Time{})
38		if err != nil {
39			t.Fatal(err)
40		}
41		// 同一次就诊下：两条已生效诊断、两条已生效医嘱。
42		activate := func(category, content string) (ID, Version) {
43			t.Helper()
44			r, err := s.CreateDraft(doc, p.ID, e.ID, category, content)
45			if err != nil {
46				t.Fatal(err)
47			}
48			v, err := s.ActivateRecord(doc, r.ID)
49			if err != nil {
50				t.Fatal(err)
51			}
52			return r.ID, v
53		}
54		d1, d1v1 := activate(Diagnosis, "诊断一内容")
55		d2, d2v1 := activate(Diagnosis, "诊断二内容")
56		o1, o1v1 := activate(Order, "医嘱一内容")
57		o2, _ := activate(Order, "医嘱二内容")
58	
59		// 接收方原先只有覆盖第一条诊断的有效限定授权。
60		start := clk.t.Add(-time.Hour)
61		end := clk.t.Add(48 * time.Hour)
62		origAuth, err := s.GrantSelective(doc, p.ID, rcv.ID, nil,
63			[]RecordSelection{sel(e.ID, Diagnosis, d1)}, start, end)
64		if err != nil {
65			t.Fatal(err)
66		}
67	
68		// 提交前的正式基线：授权列表、审计与接收方读取结果。
69		authsBefore, err := s.ListAuthorizations(doc, p.ID, "")
70		if err != nil {
71			t.Fatal(err)
72		}
73		if len(authsBefore) != 1 || authsBefore[0].ID != origAuth.ID {
74			t.Fatalf("unexpected baseline authorizations: %+v", authsBefore)
75		}
76		auditBefore, err := s.AuditEvents(doc, p.ID)
77		if err != nil {
78			t.Fatal(err)
79		}
80		grantsBefore := auditActions(auditBefore)[ActionGranted]
81		readDiagBefore, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
82		if err != nil {
83			t.Fatal(err)
84		}
85		if len(readDiagBefore.Records) != 1 || readDiagBefore.Records[0].RecordID != d1 ||
86			readDiagBefore.Records[0].VersionID != d1v1.ID {
87			t.Fatalf("unexpected baseline diagnosis read: %+v", readDiagBefore)
88		}
89		// 医嘱原本没有任何授权：明确拒绝且不携带受保护内容。
90		if res, err := s.Read(rcv, p.ID, e.ID, Order); !errors.Is(err, ErrAccessDenied) || len(res.Records) != 0 {
91			t.Fatalf("baseline order read: res=%+v err=%v, want ErrAccessDenied without content", res, err)
92		}
93	
94		// checkIntact 断言：失败尝试之后（以及重开之后），授权列表、审计与接收方
95		// 可见结果都与提交前一致——原授权的范围、有效期与撤回状态不变，没有新授权
96		// 的创建事件，接收方不能多出第二条诊断或任何医嘱。
97		checkIntact := func(label string, st *Store) {
98			t.Helper()
99	
100			auths, err := st.ListAuthorizations(doc, p.ID, "")
101			if err != nil {
102				t.Fatalf("%s: list authorizations: %v", label, err)
103			}
104			if !reflect.DeepEqual(auths, authsBefore) {
105				t.Fatalf("%s: authorization list changed:\nbefore: %+v\nafter:  %+v", label, authsBefore, auths)
106			}
107			got, err := st.GetAuthorization(doc, p.ID, origAuth.ID)
108			if err != nil {
109				t.Fatalf("%s: get original authorization: %v", label, err)
110			}
111			if len(got.Scopes) != 0 || len(got.Selections) != 1 ||
112				got.Selections[0] != sel(e.ID, Diagnosis, d1) ||
113				!got.StartsAt.Equal(origAuth.StartsAt) || !got.ExpiresAt.Equal(origAuth.ExpiresAt) ||
114				got.RevokedAt != nil {
115				t.Fatalf("%s: original authorization mutated: %+v", label, got)
116			}
117	
118			// 既有审计的内容与顺序保持原样，没有新授权的创建事件。
119			audit, err := st.AuditEvents(doc, p.ID)
120			if err != nil {
121				t.Fatalf("%s: audit: %v", label, err)
122			}
123			if !reflect.DeepEqual(audit, auditBefore) {
124				t.Fatalf("%s: audit events changed:\nbefore: %+v\nafter:  %+v", label, auditBefore, audit)
125			}
126			if got := auditActions(audit)[ActionGranted]; got != grantsBefore {
127				t.Fatalf("%s: authorization_granted events = %d, want %d", label, got, grantsBefore)
128			}
129	
130			// 接收方仍只能读到第一条诊断的当前内容，第二条诊断不出现。
131			res, err := st.Read(rcv, p.ID, e.ID, Diagnosis)
132			if err != nil {
133				t.Fatalf("%s: receiver diagnosis read: %v", label, err)
134			}
135			if !reflect.DeepEqual(res, readDiagBefore) {
136				t.Fatalf("%s: receiver diagnosis read changed:\nbefore: %+v\nafter:  %+v", label, readDiagBefore, res)
137			}
138			// 医嘱仍然整体拒绝，且不携带任何受保护内容。
139			if res, err := st.Read(rcv, p.ID, e.ID, Order); !errors.Is(err, ErrAccessDenied) || len(res.Records) != 0 {
140				t.Fatalf("%s: receiver order read: res=%+v err=%v, want ErrAccessDenied without content", label, res, err)
141			}
142		}
143	
144		// 制造本地保存失败：数据文件原位置被同名目录占据，原子改名必然失败，
145		// 与身份、范围或所选记录的合法性无关。原数据文件先挪到旁边，事后原样还原。
146		dataPath := filepath.Join(dir, dataName)
147		backupPath := dataPath + ".saved"
148		if err := os.Rename(dataPath, backupPath); err != nil {
149			t.Fatalf("backup data file: %v", err)
150		}
151		if err := os.Mkdir(dataPath, 0o755); err != nil {
152			t.Fatalf("block data path: %v", err)
153		}
154	
155		// 身份、所属患者、就诊、类别与所选记录全部合法，时间窗覆盖操作时间，
156		// 仅本地保存失败：必须明确报错，且不能伪装成参数非法、记录不存在、
157		// 跨患者或访问拒绝等业务结果。（非 nil 错误时返回值无意义，调用方必须
158		// 以错误为准；下面的正式状态断言保证它没有成为一条正式授权。）
159		newScopes := []Scope{{EncounterID: e.ID, Category: Diagnosis}}
160		newSelections := []RecordSelection{sel(e.ID, Order, o1)}
161		failedAuth, err := s.GrantSelective(doc, p.ID, rcv.ID, newScopes, newSelections, start, end)
162		if err == nil {
163			t.Fatal("grant must fail when local save fails")
164		}
165		if errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound) ||
166			errors.Is(err, ErrMismatchedPatient) || errors.Is(err, ErrAccessDenied) ||
167			errors.Is(err, ErrDeactivated) || errors.Is(err, ErrConflict) {
168			t.Fatalf("save failure surfaced as a business error: %v", err)
169		}
170		// 失败不能留下半截写入的临时文件。
171		if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
172			t.Fatalf("failed save left a temp file: %v", statErr)
173		}
174		// 失败尝试不能留下只有授权的结果：即便错误返回中携带了准备好的授权，
175		// 它也没有成为正式数据。
176		if failedAuth.ID != "" {
177			if _, getErr := s.GetAuthorization(doc, p.ID, failedAuth.ID); !errors.Is(getErr, ErrNotFound) {
178				t.Fatalf("failed grant surfaced as a stored authorization: %v", getErr)
179			}
180		}
181	
182		// 失败后：授权列表、审计与接收方可见结果全部维持提交前状态。
183		checkIntact("after failed save", s)
184	
185		// 关闭后从原数据位置重新打开：先恢复保存条件（还原原数据文件）。
186		if err := s.Close(); err != nil {
187			t.Fatal(err)
188		}
189		if err := os.Remove(dataPath); err != nil {
190			t.Fatalf("unblock data path: %v", err)
191		}
192		if err := os.Rename(backupPath, dataPath); err != nil {
193			t.Fatalf("restore data file: %v", err)
194		}
195	
196		s2 := open()
197		t.Cleanup(func() { _ = s2.Close() })
198		// 重开后仍是提交前的正式数据：失败授权与其创建事件都不存在。
199		checkIntact("after reopen", s2)
200	
201		// 保存条件恢复后：提交相同的合法授权（同患者、同接收方、同样的整类
202		// 范围与限定范围、同一时间窗）必须成功。授权窗口仍覆盖操作时间。
203		clk.t = clk.t.Add(time.Hour)
204		newAuth, err := s2.GrantSelective(doc, p.ID, rcv.ID, newScopes, newSelections, start, end)
205		if err != nil {
206			t.Fatalf("retry after save recovered: %v", err)
207		}
208		if newAuth.ID == "" || newAuth.ID == origAuth.ID {
209			t.Fatalf("retry must create a new authorization, got %+v", newAuth)
210		}
211		if !reflect.DeepEqual(newAuth.Scopes, newScopes) ||
212			!reflect.DeepEqual(newAuth.Selections, newSelections) ||
213			!newAuth.StartsAt.Equal(start) || !newAuth.ExpiresAt.Equal(end) ||
214			newAuth.RevokedAt != nil || !newAuth.CreatedAt.Equal(clk.t) {
215			t.Fatalf("new authorization wrong: %+v", newAuth)
216		}
217	
218		// 授权列表恰为两条：原授权在前且原样保留，新授权完整可查。
219		auths, err := s2.ListAuthorizations(doc, p.ID, "")
220		if err != nil {
221			t.Fatal(err)
222		}
223		if len(auths) != 2 {
224			t.Fatalf("authorizations after retry = %d, want 2", len(auths))
225		}
226		for _, a := range auths {
227			if a.ID == origAuth.ID && !reflect.DeepEqual(a, authsBefore[0]) {
228				t.Fatalf("original authorization changed by retry:\nbefore: %+v\nafter:  %+v", authsBefore[0], a)
229			}
230		}
231		gotNew, err := s2.GetAuthorization(doc, p.ID, newAuth.ID)
232		if err != nil {
233			t.Fatalf("get new authorization: %v", err)
234		}
235		if !reflect.DeepEqual(gotNew, newAuth) {
236			t.Fatalf("stored new authorization differs:\ncreated: %+v\nstored:  %+v", newAuth, gotNew)
237		}
238	
239		// 审计相对提交前基线只新增一条授权创建事件，指向成功创建的授权并记录
240		// 实际操作身份与时间；既有事件的内容与顺序原样保留。
241		audit, err := s2.AuditEvents(doc, p.ID)
242		if err != nil {
243			t.Fatal(err)
244		}
245		if len(audit) != len(auditBefore)+1 || !reflect.DeepEqual(audit[:len(auditBefore)], auditBefore) {
246			t.Fatalf("audit after retry:\nbefore: %+v\nafter:  %+v", auditBefore, audit)
247		}
248		last := audit[len(audit)-1]
249		if last.Action != ActionGranted || last.ObjectType != "authorization" ||
250			last.ObjectID != newAuth.ID || last.ActorID != doc.ID ||
251			last.PatientID != p.ID || !last.OccurredAt.Equal(clk.t) {
252			t.Fatalf("unexpected new audit event: %+v", last)
253		}
254		if got := auditActions(audit)[ActionGranted]; got != grantsBefore+1 {
255			t.Fatalf("authorization_granted events = %d, want %d", got, grantsBefore+1)
256		}
257	
258		// 患者全程未停用、两条授权均在有效期内：读取结果的变化只来自新授权
259		// 成功保存。接收方现在能读到两条诊断各自的当前版本。
260		res, err := s2.Read(rcv, p.ID, e.ID, Diagnosis)
261		if err != nil {
262			t.Fatalf("diagnosis read after retry: %v", err)
263		}
264		if len(res.Records) != 2 {
265			t.Fatalf("diagnosis read after retry = %+v, want 2 records", res)
266		}
267		diagByID := map[ID]EffectiveRecord{}
268		for _, rec := range res.Records {
269			diagByID[rec.RecordID] = rec
270		}
271		if got := diagByID[d1]; got.VersionID != d1v1.ID || got.Content != "诊断一内容" {
272			t.Fatalf("diagnosis d1 wrong after retry: %+v", got)
273		}
274		if got := diagByID[d2]; got.VersionID != d2v1.ID || got.Content != "诊断二内容" {
275			t.Fatalf("diagnosis d2 wrong after retry: %+v", got)
276		}
277	
278		// 医嘱不再整体拒绝：明确选中的第一条医嘱可读，第二条医嘱仍不进入
279		// 可见结果。
280		res, err = s2.Read(rcv, p.ID, e.ID, Order)
281		if err != nil {
282			t.Fatalf("order read after retry: %v", err)
283		}
284		if len(res.Records) != 1 || res.Records[0].RecordID != o1 ||
285			res.Records[0].VersionID != o1v1.ID || res.Records[0].Content != "医嘱一内容" {
286			t.Fatalf("order read after retry = %+v, want only selected o1", res)
287		}
288		if readRecordIDs(res)[o2] {
289			t.Fatal("unselected order o2 must not be visible")
290		}
291	}
